    const scripts = parsed['scripts'];
    if (!isJsonObject(scripts)) return false;
    return typeof scripts['emit'] === 'string' && scripts['emit'].length > 0;
  } catch {
    return false;
  }
}

async function packageJsonHasBuildContractSpaceScript(dir: string): Promise<boolean> {
  const pkgPath = join(dir, 'package.json');
  if (!(await pathExists(pkgPath))) return false;
  const raw = await readFile(pkgPath, 'utf-8');
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!isJsonObject(parsed)) return false;
    const scripts = parsed['scripts'];
    if (!isJsonObject(scripts)) return false;
    return (
      typeof scripts['build:contract-space'] === 'string' &&
      scripts['build:contract-space'].length > 0
    );
  } catch {
    return false;
  }
}

async function resolveEmitInvocation(configDir: string): Promise<{
  readonly cwd: string;
  readonly args: string[];
  readonly key: string;
}> {
  let dir = configDir;
  while (dir.startsWith(projectRoot)) {
    if (await packageJsonHasEmitScript(dir)) {
      return { cwd: dir, args: ['emit'], key: `script:${dir}` };
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  const configPath = join(configDir, 'prisma.config.ts');
  return {
    cwd: projectRoot,
    args: ['exec', 'prisma-next', 'contract', 'emit', '--config', configPath],
    key: `config:${configPath}`,
  };
}

async function runEmit(configDir: string): Promise<void> {
  const { cwd, args } = await resolveEmitInvocation(configDir);
  await execFileAsync('pnpm', args, { cwd, env: process.env });
}

const configDirs = await findPrismaNextConfigDirs(projectRoot);
const emitKeys = new Set<string>();
const targets: Array<{ configDir: string; contractPath: string }> = [];

for (const configDir of configDirs) {
  if (await packageJsonHasBuildContractSpaceScript(configDir)) continue;
  const contractPath = await resolveContractJson(configDir);
  if (contractPath === null) continue;
  const raw = await readFile(contractPath, 'utf-8');
  if (!contractNeedsPublicDefaultMigration(raw)) continue;
  const { key } = await resolveEmitInvocation(configDir);
  if (emitKeys.has(key)) continue;
  emitKeys.add(key);
  targets.push({ configDir, contractPath });
}

if (targets.length === 0) {
  console.error(`No Postgres public-default migration candidates under ${projectRoot}.`);
  process.exit(dryRun ? 0 : 1);
}

let needsFix = 0;

for (const { configDir, contractPath } of targets) {
  const rel = configDir.slice(projectRoot.length + 1) || '.';
  const raw = await readFile(contractPath, 'utf-8');
  if (!contractNeedsPublicDefaultMigration(raw)) {
    console.log(`OK    ${rel}`);
    continue;
  }
  needsFix += 1;
  if (dryRun) {
    console.log(`WOULD RE-EMIT  ${rel}`);
    continue;
  }
  console.log(`EMIT  ${rel}`);
  await runEmit(configDir);
}

console.log();
console.log(
  `${targets.length} contract-space(s): ${needsFix} ${dryRun ? 'needing re-emit' : 're-emitted'}.`,
);

if (dryRun && needsFix > 0) process.exit(1);

/**
 * Brings on-disk `migration.json` manifests into the slimmed 0.12 metadata
 * model: drops the now-removed `labels` and `hints` keys and recomputes
 * `migrationHash` over the surviving metadata envelope + sibling `ops.json`.
 *
 * Background: starting at the 0.12 release the migration manifest schema is
 * closed (`'+': 'reject'`) — `labels` and `hints` are no longer part of the
 * model, so any manifest still carrying either key fails to load with
 * `INVALID_MANIFEST` naming the offending key. The two fields also no longer
 * participate in the content-addressed migration identity: `migrationHash` is
 * now computed over `{ from, to, providedInvariants, createdAt }` plus the
 * sibling operations, so every migrated manifest gets a freshly recomputed
 * hash over the slimmed envelope.
 *
 * Before 0.12 the on-disk shape was:
 *
 *   {
 *     "from": null,
 *     "to": "sha256:…",
 *     "labels": [],
 *     "providedInvariants": ["…"],
 *     "createdAt": "2026-…",
 *     "hints": { "used": [], "applied": [], "plannerVersion": "2.0.0" },
 *     "migrationHash": "sha256:…"
 *   }
 *
 * Starting at 0.12 the same manifest is:
 *
 *   {
 *     "from": null,
 *     "to": "sha256:…",
 *     "providedInvariants": ["…"],
 *     "createdAt": "2026-…",
 *     "migrationHash": "sha256:…"   // recomputed over the slimmed envelope
 *   }
 *
 * Format-preserving edit: rather than reparse-and-reserialise (which would
 * reflow every value to a single canonical style and bloat the diff), this
 * codemod performs a surgical text edit — it removes only the `labels` and
 * `hints` top-level key lines and swaps the `migrationHash` value in place.
 * Every other byte (key order, indentation, and whether arrays like
 * `providedInvariants` are written inline or expanded) is left exactly as the
 * authoring tool wrote it, so the diff is limited to the two removed keys and
 * the new hash value.
 *
 * Confinement: an on-disk migration package is a `migration.json` paired with
 * a sibling `ops.json` (the operations the hash is computed over). The walk
 * keys off that pair rather than off a `migrations/` directory name, because
 * migration packages live under several roots in practice (`migrations/`,
 * `migration-fixtures/`, …); a `migration.json` with no sibling `ops.json` is
 * not a complete package and is left untouched.
 *
 * The hash algorithm is replicated inline (canonicalisation rules from
 * `@internal/framework-components` `canonicalizeJson` + the migration-tools
 * `computeMigrationHash`) so this script stays self-contained — consumers run
 * it via `pnpm exec tsx` from their project root with no dependency on any
 * `@internal/*` package being resolvable from that root.
 *
 * The codemod is idempotent: an already-slimmed manifest carries no
 * `labels`/`hints` and already has its recomputed hash, so the edit is a no-op
 * and the file is left untouched.
 *
 * Flags:
 *   --check   dry-run; lists manifests that still need fixing and exits 1 if
 *             any remain.
 */
import { createHash } from 'node:crypto';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';

const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build']);

const dryRun = process.argv.includes('--check');
const projectRoot = process.cwd();

// --- Inline canonicalisation + hash --------------------------------------
// Replicated from `@internal/framework-components` `canonicalizeJson`
// (sortKeys + JSON.stringify) and the migration-tools `computeMigrationHash`.
// Kept inline so the script has no `@internal/*` import — pnpm's strict
// node_modules layout won't resolve transitive framework deps from a
// consumer's project root.

function sortKeys(value: unknown): unknown {
  if (value === null || typeof value !== 'object') {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(sortKeys);
  }
  const sorted: Record<string, unknown> = Object.create(null);
  for (const [key, entry] of Object.entries(value).sort(([a], [b]) =>
    a < b ? -1 : a > b ? 1 : 0,
  )) {
    sorted[key] = sortKeys(entry);
  }
  return sorted;
}

function canonicalizeJson(value: unknown): string {
  return JSON.stringify(sortKeys(value));
}

function sha256Hex(input: string): string {
  return createHash('sha256').update(input).digest('hex');
}

/**
 * Content-addressed migration hash over (metadata envelope, ops). The
 * `migrationHash` field is stripped before hashing so the same function works
 * at write time (no hash yet) and at recompute time (rehashing an
 * already-attested record over the slimmed envelope).
 */
function computeMigrationHash(metadata: Record<string, unknown>, ops: unknown): string {
  const { migrationHash: _migrationHash, ...strippedMeta } = metadata;

  const partHashes = [canonicalizeJson(strippedMeta), canonicalizeJson(ops)].map(sha256Hex);
  return `sha256:${sha256Hex(canonicalizeJson(partHashes))}`;
}

// --- Format-preserving text surgery --------------------------------------

/**
 * Returns the index just past the end of the JSON value that starts at
 * `start` (which must point at the value's first character). Handles strings
 * (with escapes), nested objects/arrays, and primitives. Used to locate the
 * full span of a top-level key's value when removing the key from the raw
 * text without reparsing the whole document.
 */
function scanValueEnd(text: string, start: number): number {
  const c = text[start];

  if (c === '"') {
    let i = start + 1;
    while (i < text.length) {
      if (text[i] === '\\') {
        i += 2;
        continue;
      }
      if (text[i] === '"') return i + 1;
      i += 1;
    }
    throw new Error('unterminated string while scanning JSON value');
  }

  if (c === '{' || c === '[') {
    const open = c;
    const close = c === '{' ? '}' : ']';
    let depth = 0;
    let i = start;
    while (i < text.length) {
      const ch = text[i];
      if (ch === '"') {
        i = scanValueEnd(text, i);
        continue;
      }
      if (ch === open) depth += 1;
      else if (ch === close) {
        depth -= 1;
        if (depth === 0) return i + 1;
      }
      i += 1;
    }
    throw new Error('unterminated container while scanning JSON value');
  }

  // Primitive (number / true / false / null) — run to the next structural
  // terminator.
  let i = start;
  while (i < text.length && !',}]\r\n \t'.includes(text[i]!)) i += 1;
  return i;
}

/**
 * Removes a top-level object key (and its value) from `text`, preserving the
 * surrounding bytes exactly. No-op (returns `text`) if the key is absent.
 * Only the top-level `labels` / `hints` keys are ever passed here; both always
 * precede the trailing `migrationHash` key, so a removed key always carries a
 * trailing comma that is consumed along with the line.
 */
function removeTopLevelKey(text: string, key: string): string {
  // A top-level key is the only occurrence of `"key":` preceded by a newline
  // (line 1 is the opening `{`). Tolerant of any indentation width.
  const re = new RegExp(`\\n([ \\t]*)"${key}"[ \\t]*:[ \\t]*`);
  const match = re.exec(text);
  if (match === null) return text;

  const lineStart = match.index + 1; // position just after the leading newline
  const valueStart = match.index + match[0].length;
  let after = scanValueEnd(text, valueStart);

  while (text[after] === ' ' || text[after] === '\t') after += 1;
  if (text[after] === ',') after += 1;
  if (text[after] === '\r') after += 1;
  if (text[after] === '\n') after += 1;

  return text.slice(0, lineStart) + text.slice(after);
}

function replaceMigrationHash(text: string, oldHash: string, newHash: string): string {
  if (oldHash === newHash) return text;
  // Tolerate any whitespace around the colon (`"migrationHash":"…"`,
  // `"migrationHash" : "…"`), matching the leniency of `removeTopLevelKey`.
  const escapedOld = oldHash.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`("migrationHash"[ \\t]*:[ \\t]*)"${escapedOld}"`);
  const match = re.exec(text);
  if (match === null) {
    throw new Error('could not locate the migrationHash value to replace');
  }
  return text.replace(re, (_full, prefix: string) => `${prefix}"${newHash}"`);
}

// --- Filesystem walk ------------------------------------------------------

async function findMigrationManifests(root: string): Promise<string[]> {
  const out: string[] = [];

  async function walk(dir: string): Promise<void> {
    let entries: Awaited<ReturnType<typeof readdir>>;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      // Unreadable directory — skip silently. The consumer's project root may
      // legitimately contain restricted directories.
      return;
    }
    for (const entry of entries) {
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name)) continue;
        await walk(join(dir, entry.name));
      } else if (entry.isFile() && entry.name === 'migration.json') {
        out.push(join(dir, entry.name));
      }
    }
  }

  await walk(root);
  return out.sort();
}

// --- Per-file transform ---------------------------------------------------

/** Narrows an arbitrary JSON-parsed value to a plain object (manifest shape). */
function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

type Status = 'already-clean' | 'needs-fix' | 'fixed' | 'skipped-no-ops';

interface Result {
  readonly path: string;
  readonly status: Status;
}

async function processFile(path: string): Promise<Result> {
  const raw = await readFile(path, 'utf-8');

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(
      `${path}: not valid JSON (${error instanceof Error ? error.message : String(error)})`,
    );
  }
  if (!isJsonObject(parsed)) {
    return { path, status: 'already-clean' }; // not a manifest object
  }
  const metadata = parsed;

  // A complete on-disk migration package pairs `migration.json` with a sibling
  // `ops.json` (the operations the hash is computed over); without it we cannot
  // recompute the hash, so this is not a package we should touch.
  const opsPath = join(dirname(path), 'ops.json');
  let ops: unknown;
  try {
    ops = JSON.parse(await readFile(opsPath, 'utf-8'));
  } catch {
    return { path, status: 'skipped-no-ops' };
  }

  // Recompute over the slimmed envelope (canonicalisation is order/whitespace
  // independent, so the parsed object is the right input regardless of on-disk
  // formatting). `computeMigrationHash` strips `migrationHash` internally.
  const slimmed = { ...metadata };
  delete slimmed['labels'];
  delete slimmed['hints'];
  const newHash = computeMigrationHash(slimmed, ops);

  let out = raw;
  out = removeTopLevelKey(out, 'labels');
  out = removeTopLevelKey(out, 'hints');

  const oldHash = metadata['migrationHash'];
  if (typeof oldHash === 'string') {
    out = replaceMigrationHash(out, oldHash, newHash);
  } else if (out !== raw) {
    // labels/hints were present but there is no string migrationHash to update
    // — a malformed manifest we refuse to guess at.
    throw new Error(`${path}: manifest is missing a string \`migrationHash\` field`);
  }

  if (out === raw) {
    return { path, status: 'already-clean' };
  }
  if (!dryRun) await writeFile(path, out, 'utf-8');
  return { path, status: dryRun ? 'needs-fix' : 'fixed' };
}

// --- Driver ---------------------------------------------------------------

const manifests = await findMigrationManifests(projectRoot);
if (manifests.length === 0) {
  console.error(`No migration.json files found under ${projectRoot}.`);
  process.exit(1);
}

let changed = 0;
let alreadyClean = 0;
let skipped = 0;
for (const path of manifests) {
  const result = await processFile(path);
  const rel = path.slice(projectRoot.length + 1);
  if (result.status === 'already-clean') {
    alreadyClean += 1;
  } else if (result.status === 'skipped-no-ops') {
    skipped += 1;
    console.log(`SKIP  ${rel}  (no sibling ops.json — not a migration package)`);
  } else {
    changed += 1;
    const verb = dryRun ? 'WOULD FIX' : 'FIXED';
    console.log(`${verb} ${rel}`);
  }
}

console.log();
console.log(
  `${manifests.length} manifest(s) scanned: ${changed} ${dryRun ? 'needing fix' : 'fixed'}, ${alreadyClean} already clean${skipped > 0 ? `, ${skipped} skipped (no ops.json)` : ''}.`,
);

if (dryRun && changed > 0) process.exit(1);

/**
 * Re-emits every contract whose MTI variant tables (PSL `@@base(Parent, "tag")`
 * models that carry their own `@@map`) predate the base-PK link column.
 *
 * Starting at this release, a `@@base` variant stored in its own table
 * materialises a base-PK link column in storage: the variant table gains an
 * `id` column, a single-column primary key on it, and a cascading foreign key
 * referencing the base table's primary key. Before the change, the variant
 * table held only the variant-specific columns with no primary key.
 *
 * Detection: a contract is a candidate when its domain carries a model with a
 * `base` reference (an MTI variant) whose matching storage table has no
 * `primaryKey` — the pre-change shape. After re-emit the table gains its
 * `id` PK + cascading FK and the contract's `storageHash` changes.
 *
 * Dispatch: walks the project root for `prisma.config.ts` directories,
 * resolves each space's committed `contract.json`, and re-emits when a variant
 * table still lacks its link column. Uses the nearest ancestor `package.json`
 * `scripts.emit` when present; otherwise runs
 * `prisma-next contract emit --config <path>`.
 *
 * Flags:
 *   --check   dry-run; lists contract-spaces that still need re-emitting and
 *             exits 1 if any remain.
 */
import { execFile } from 'node:child_process';
import { access, readdir, readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);

const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build']);

const dryRun = process.argv.includes('--check');
const projectRoot = process.cwd();

async function pathExists(path: string): Promise<boolean> {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

async function findPrismaNextConfigDirs(root: string): Promise<string[]> {
  const out: string[] = [];

  async function walk(dir: string): Promise<void> {
    let entries: Awaited<ReturnType<typeof readdir>>;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name)) continue;
        await walk(join(dir, entry.name));
      } else if (entry.isFile() && entry.name === 'prisma.config.ts') {
        out.push(dir);
      }
    }
  }

  await walk(root);
  return out.sort();
}

function contractJsonCandidates(configDir: string): string[] {
  return [
    join(configDir, 'src', 'contract.json'),
    join(configDir, 'src', 'prisma', 'contract.json'),
    join(configDir, 'prisma', 'contract.json'),
    join(configDir, 'contract.json'),
  ];
}

async function resolveContractJson(configDir: string): Promise<string | null> {
  for (const candidate of contractJsonCandidates(configDir)) {
    if (await pathExists(candidate)) return candidate;
  }
  return null;
}

/**
 * A contract needs the MTI link-column migration when any of its domain models
 * is an MTI variant (carries a `base` reference) whose matching storage table
 * has no `primaryKey` — the pre-change shape that lacks the link column.
 */
function contractNeedsMtiLinkColumns(raw: string): boolean {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return false;
  }
  if (!isJsonObject(parsed)) return false;

  const domain = parsed['domain'];
  const storage = parsed['storage'];
  if (!isJsonObject(domain) || !isJsonObject(storage)) return false;

  const domainNamespaces = domain['namespaces'];
  const storageNamespaces = storage['namespaces'];
  if (!isJsonObject(domainNamespaces) || !isJsonObject(storageNamespaces)) return false;

  for (const [nsKey, ns] of Object.entries(domainNamespaces)) {
    if (!isJsonObject(ns)) continue;
    const models = ns['models'];
    if (!isJsonObject(models)) continue;
    for (const model of Object.values(models)) {
      if (!isJsonObject(model)) continue;
      if (!isJsonObject(model['base'])) continue;
      const variantStorage = model['storage'];
      if (!isJsonObject(variantStorage)) continue;
      const tableName = variantStorage['table'];
      // The variant table's namespace defaults to the model's enclosing domain
      // namespace when `storage.namespace` is absent.
      const namespaceId =
        typeof variantStorage['namespace'] === 'string' ? variantStorage['namespace'] : nsKey;
      if (typeof tableName !== 'string') continue;
      const storageNs = storageNamespaces[namespaceId];
      if (!isJsonObject(storageNs)) continue;
      const tables = storageNs['tables'];
      if (!isJsonObject(tables)) continue;
      const table = tables[tableName];
      if (!isJsonObject(table)) continue;
      if (table['primaryKey'] === undefined || table['primaryKey'] === null) {
        return true;
      }
    }
  }
  return false;
}

async function packageJsonHasScript(dir: string, name: string): Promise<boolean> {
  const pkgPath = join(dir, 'package.json');
  if (!(await pathExists(pkgPath))) return false;
  const raw = await readFile(pkgPath, 'utf-8');
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!isJsonObject(parsed)) return false;
    const scripts = parsed['scripts'];
    if (!isJsonObject(scripts)) return false;
    const value = scripts[name];
    return typeof value === 'string' && value.length > 0;
  } catch {
    return false;
  }
}

async function resolveEmitInvocation(configDir: string): Promise<{
  readonly cwd: string;
  readonly args: string[];
  readonly key: string;
}> {
  let dir = configDir;
  while (dir.startsWith(projectRoot)) {
    if (await packageJsonHasScript(dir, 'emit')) {
      return { cwd: dir, args: ['emit'], key: `script:${dir}` };
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  const configPath = join(configDir, 'prisma.config.ts');
  return {
    cwd: projectRoot,
    args: ['exec', 'prisma-next', 'contract', 'emit', '--config', configPath],
    key: `config:${configPath}`,
  };
}

async function runEmit(configDir: string): Promise<void> {
  const { cwd, args } = await resolveEmitInvocation(configDir);
  await execFileAsync('pnpm', args, { cwd, env: process.env });
}

const configDirs = await findPrismaNextConfigDirs(projectRoot);
const emitKeys = new Set<string>();
const targets: Array<{ configDir: string; contractPath: string }> = [];

for (const configDir of configDirs) {
  if (await packageJsonHasScript(configDir, 'build:contract-space')) continue;
  const contractPath = await resolveContractJson(configDir);
  if (contractPath === null) continue;
  const raw = await readFile(contractPath, 'utf-8');
  if (!contractNeedsMtiLinkColumns(raw)) continue;
  const { key } = await resolveEmitInvocation(configDir);
  if (emitKeys.has(key)) continue;
  emitKeys.add(key);
  targets.push({ configDir, contractPath });
}

if (targets.length === 0) {
  console.error(`No MTI variant link-column migration candidates under ${projectRoot}.`);
  process.exit(dryRun ? 0 : 1);
}

let needsFix = 0;

for (const { configDir, contractPath } of targets) {
  const rel = configDir.slice(projectRoot.length + 1) || '.';
  const raw = await readFile(contractPath, 'utf-8');
  if (!contractNeedsMtiLinkColumns(raw)) {
    console.log(`OK    ${rel}`);
    continue;
  }
  needsFix += 1;
  if (dryRun) {
    console.log(`WOULD RE-EMIT  ${rel}`);
    continue;
  }
  console.log(`EMIT  ${rel}`);
  await runEmit(configDir);
}

console.log();
console.log(
  `${targets.length} contract-space(s): ${needsFix} ${dryRun ? 'needing re-emit' : 're-emitted'}.`,
);

if (dryRun && needsFix > 0) process.exit(1);

/**
 * Removes bare migration op factory imports and rewrites call-sites to use
 * the method form on `this` (0.13 → 0.14):
 *
 *   dropColumn(schema, table, col)  →  this.dropColumn({ schema, table, column: col })
 *   setNotNull(schema, table, col)  →  this.setNotNull({ schema, table, column: col })
 *   setDefault(schema, table, col, sql)
 *     → this.setDefault({ schema, table, column: col, defaultSql: sql })
 *   addPrimaryKey(schema, table, name, cols)
 *     → this.addPrimaryKey({ schema, table, constraint: name, columns: cols })
 *   addForeignKey(schema, table, { name, columns, references, onDelete })
 *     → this.addForeignKey({ schema, table, foreignKey: { name, columns, references, onDelete } })
 *   addCheckConstraint(schema, table, name, col, vals)
 *     → this.addCheckConstraint({ schema, table, constraint: name, column: col, values: vals })
 *   createIndex(schema, table, idx, cols)
 *     → this.createIndex({ schema, table, index: idx, columns: cols })
 *   installExtension({ ... })  →  this.installExtension({ ... })
 *
 * Applies to files importing from '@internal/postgres/migration',
 * '@internal/target-postgres/migration', '@internal/sqlite/migration', or
 * '@internal/target-sqlite/migration'. Handles only call-sites where all
 * arguments are simple literals or identifiers on a single logical token (no
 * multi-line positional calls). For complex cases the type-checker will flag
 * remaining sites.
 *
 * Run from the project root:
 *   pnpm exec tsx <path-to-this-file>
 */

import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'pathe';

const FACTORY_NAMES = [
  'dropColumn',
  'setNotNull',
  'setDefault',
  'addPrimaryKey',
  'addForeignKey',
  'addCheckConstraint',
  'createIndex',
  'installExtension',
];

/**
 * Strip bare factory names from import declarations (handles both single-line
 * and multi-line `import { ... } from '...'` forms). Removes the whole import
 * line (including trailing newline) when all names are factories.
 */
function stripFactoriesFromImports(src: string): string {
  const importRe =
    /^[^\S\n]*import\s*\{([^}]+)\}\s*from\s*'@internal\/(?:postgres|target-postgres|sqlite|target-sqlite)\/migration'[^\S\n]*;?[^\S\n]*\n?/gms;
  return src.replace(importRe, (full, nameBlock) => {
    const names = nameBlock
      .split(',')
      .map((n: string) => n.trim())
      .filter((n: string) => n.length > 0 && !FACTORY_NAMES.includes(n));
    if (names.length === 0) return '';
    const fromClause = full.slice(full.indexOf('}') + 1);
    return `import { ${names.join(', ')} }${fromClause}`;
  });
}

/** Reads a quoted string or bare identifier/bracket-balanced token starting at offset. */
function readToken(src: string, offset: number): { value: string; end: number } | null {
  let i = offset;
  while (i < src.length && src[i] === ' ') i++;
  if (i >= src.length) return null;
  if (src[i] === "'" || src[i] === '"' || src[i] === '`') {
    const q = src[i];
    let end = i + 1;
    while (end < src.length && src[end] !== q) end++;
    return { value: src.slice(i, end + 1), end: end + 1 };
  }
  let depth = 0;
  let end = i;
  while (end < src.length) {
    const c = src[end];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') {
      if (depth === 0) break;
      depth--;
    } else if ((c === ',' || c === '\n') && depth === 0) break;
    end++;
  }
  return { value: src.slice(i, end).trim(), end };
}

type Rewrite = {
  pattern: RegExp;
  rewrite: (m: RegExpExecArray) => string | null;
};

const rewrites: Rewrite[] = [
  // dropColumn(schema, table, column)
  {
    pattern: /\bdropColumn\(/g,
    rewrite(m) {
      const rest = m.input.slice(m.index + m[0].length);
      const s = readToken(rest, 0);
      if (!s) return null;
      const t = readToken(rest, s.end + 1);
      if (!t) return null;
      const c = readToken(rest, t.end + 1);
      if (!c) return null;
      return `this.dropColumn({ schema: ${s.value}, table: ${t.value}, column: ${c.value} })`;
    },
  },
  // setNotNull(schema, table, column)
  {
    pattern: /\bsetNotNull\(/g,
    rewrite(m) {
      const rest = m.input.slice(m.index + m[0].length);
      const s = readToken(rest, 0);
      if (!s) return null;
      const t = readToken(rest, s.end + 1);
      if (!t) return null;
      const c = readToken(rest, t.end + 1);
      if (!c) return null;
      return `this.setNotNull({ schema: ${s.value}, table: ${t.value}, column: ${c.value} })`;
    },
  },
  // setDefault(schema, table, column, defaultSql)
  {
    pattern: /\bsetDefault\(/g,
    rewrite(m) {
      const rest = m.input.slice(m.index + m[0].length);
      const s = readToken(rest, 0);
      if (!s) return null;
      const t = readToken(rest, s.end + 1);
      if (!t) return null;
      const c = readToken(rest, t.end + 1);
      if (!c) return null;
      const d = readToken(rest, c.end + 1);
      if (!d) return null;
      return `this.setDefault({ schema: ${s.value}, table: ${t.value}, column: ${c.value}, defaultSql: ${d.value} })`;
    },
  },
  // addPrimaryKey(schema, table, constraintName, columns)
  {
    pattern: /\baddPrimaryKey\(/g,
    rewrite(m) {
      const rest = m.input.slice(m.index + m[0].length);
      const s = readToken(rest, 0);
      if (!s) return null;
      const t = readToken(rest, s.end + 1);
      if (!t) return null;
      const n = readToken(rest, t.end + 1);
      if (!n) return null;
      const c = readToken(rest, n.end + 1);
      if (!c) return null;
      return `this.addPrimaryKey({ schema: ${s.value}, table: ${t.value}, constraint: ${n.value}, columns: ${c.value} })`;
    },
  },
  // addCheckConstraint(schema, table, constraintName, column, values)
  {
    pattern: /\baddCheckConstraint\(/g,
    rewrite(m) {
      const rest = m.input.slice(m.index + m[0].length);
      const s = readToken(rest, 0);
      if (!s) return null;
      const t = readToken(rest, s.end + 1);
      if (!t) return null;
      const n = readToken(rest, t.end + 1);
      if (!n) return null;
      const c = readToken(rest, n.end + 1);
      if (!c) return null;
      const v = readToken(rest, c.end + 1);
      if (!v) return null;
      return `this.addCheckConstraint({ schema: ${s.value}, table: ${t.value}, constraint: ${n.value}, column: ${c.value}, values: ${v.value} })`;
    },
  },
  // createIndex(schema, table, indexName, columns)
  {
    pattern: /\bcreateIndex\(/g,
    rewrite(m) {
      const rest = m.input.slice(m.index + m[0].length);
      const s = readToken(rest, 0);
      if (!s) return null;
      const t = readToken(rest, s.end + 1);
      if (!t) return null;
      const idx = readToken(rest, t.end + 1);
      if (!idx) return null;
      const c = readToken(rest, idx.end + 1);
      if (!c) return null;
      return `this.createIndex({ schema: ${s.value}, table: ${t.value}, index: ${idx.value}, columns: ${c.value} })`;
    },
  },
  // addForeignKey(schema, table, { ... }) — wraps opts in `foreignKey:`
  {
    pattern: /\baddForeignKey\(/g,
    rewrite(m) {
      const rest = m.input.slice(m.index + m[0].length);
      const s = readToken(rest, 0);
      if (!s) return null;
      const t = readToken(rest, s.end + 1);
      if (!t) return null;
      const opts = readToken(rest, t.end + 1);
      if (!opts) return null;
      return `this.addForeignKey({ schema: ${s.value}, table: ${t.value}, foreignKey: ${opts.value} })`;
    },
  },
];

function applyRewrites(src: string): string {
  // installExtension already takes an object — just prepend `this.`
  let out = src.replace(/(?<!this\.)(?<!\.)\binstallExtension\(/g, 'this.installExtension(');

  for (const { pattern, rewrite } of rewrites) {
    pattern.lastIndex = 0;
    let result = '';
    let last = 0;
    let match = pattern.exec(out);
    while (match !== null) {
      const before = out.slice(Math.max(0, match.index - 5), match.index);
      if (before.endsWith('this.')) {
        result += out.slice(last, match.index + match[0].length);
        last = match.index + match[0].length;
        match = pattern.exec(out);
        continue;
      }
      const replacement = rewrite(match);
      if (replacement === null) {
        result += out.slice(last, match.index + match[0].length);
        last = match.index + match[0].length;
        match = pattern.exec(out);
        continue;
      }
      // Find the matching closing paren for the original call
      let depth = 1;
      let end = match.index + match[0].length;
      while (end < out.length && depth > 0) {
        if (out[end] === '(') depth++;
        else if (out[end] === ')') depth--;
        end++;
      }
      result += out.slice(last, match.index) + replacement;
      last = end;
      pattern.lastIndex = last;
      match = pattern.exec(out);
    }
    out = result + out.slice(last);
  }
  return out;
}

function processFile(src: string): string {
  const MIGRATION_IMPORT_RE =
    /import\s*\{[^}]+\}\s*from\s*'@internal\/(?:postgres|target-postgres|sqlite|target-sqlite)\/migration'/s;

  if (!MIGRATION_IMPORT_RE.test(src)) return src;

  const withImports = stripFactoriesFromImports(src);
  return applyRewrites(withImports);
}

const raw = execSync(
  'git ls-files --cached --others --exclude-standard -- "**migration.ts" "migration.ts"',
  { encoding: 'utf-8' },
).trim();

const files = raw
  .split('\n')
  .filter(Boolean)
  .filter((f) => f.endsWith('migration.ts'));

let changed = 0;
for (const file of files) {
  const abs = join(process.cwd(), file);
  let content: string;
  try {
    content = readFileSync(abs, 'utf-8');
  } catch {
    continue;
  }
  const relevant =
    content.includes("from '@internal/postgres/migration'") ||
    content.includes("from '@internal/target-postgres/migration'") ||
    content.includes("from '@internal/sqlite/migration'") ||
    content.includes("from '@internal/target-sqlite/migration'");
  if (!relevant) continue;

  const updated = processFile(content);
  if (updated !== content) {
    writeFileSync(abs, updated, 'utf-8');
    console.log(`updated ${file}`);
    changed++;
  }
}
console.log(`done — ${changed} file(s) updated`);

/**
 * Renames uuid field presets (0.13 → 0.14):
 *   Before: field.uuid()       / field.id.uuidv4()       / field.id.uuidv7()
 *   After:  field.uuidString() / field.id.uuidv4String() / field.id.uuidv7String()
 *
 * Run from the project root: pnpm exec tsx <path-to-this-file>
 */

import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'pathe';

const replacements: Array<[RegExp, string]> = [
  [/\bfield\.id\.uuidv4\(\)/g, 'field.id.uuidv4String()'],
  [/\bfield\.id\.uuidv7\(\)/g, 'field.id.uuidv7String()'],
  [/\bfield\.uuid\(\)/g, 'field.uuidString()'],
];

const raw = execSync('git ls-files --cached --others --exclude-standard -- "*.ts"', {
  encoding: 'utf-8',
}).trim();

const files = raw.split('\n').filter(Boolean);
let changed = 0;
for (const file of files) {
  const abs = join(process.cwd(), file);
  let content: string;
  try {
    content = readFileSync(abs, 'utf-8');
  } catch {
    continue;
  }
  const original = content;
  for (const [pattern, replacement] of replacements) {
    content = content.replace(pattern, replacement);
  }
  if (content !== original) {
    writeFileSync(abs, content, 'utf-8');
    console.log(`updated ${file}`);
    changed++;
  }
}
console.log(`done — ${changed} file(s) updated`);

/**
 * Brings checked-in `migrations/` trees onto the 0.17 bare-hex hash
 * representation: strips the legacy `sha256:` prefix from every hash literal,
 * maps the empty-tree sentinel `sha256:empty` to `empty`, recomputes each
 * migration's `migrationHash` over the bare-hex content, and repoints
 * `refs/*.json` at the recomputed hashes.
 *
 * Background: starting at the 0.17 release, content hashes are bare
 * lowercase hex — the `sha256:` prefix is gone from every surface (emitted
 * `contract.json` / `contract.d.ts`, migration manifests, refs, CLI output,
 * and the marker/ledger tables). The algorithm never varied per hash, so the
 * prefix carried no information; a format change is signalled by the hash
 * value changing, not by an in-band tag. Loaders now reject the legacy
 * prefixed form outright.
 *
 * Two distinct effects on checked-in migration artifacts:
 *
 *   - Contract hashes (`from` / `to` in `migration.json`, `storageHash` /
 *     `profileHash` in contract snapshots and `.d.ts` branded literals,
 *     `storageHash` stamps inside `ops.json`) keep their VALUE — only the
 *     `sha256:` prefix drops.
 *   - `migrationHash` VALUES change, because the hashed manifest bytes embed
 *     the (now bare) `from` / `to` strings. Every manifest gets a freshly
 *     recomputed hash, and every `refs/*.json` that pointed at an old
 *     migration hash is rewritten to the recomputed one.
 *
 * Before 0.17 a manifest was:
 *
 *   {
 *     "from": "sha256:8ee1e7ce…",
 *     "to": "sha256:059f3f35…",
 *     "providedInvariants": [],
 *     "createdAt": "2026-…",
 *     "migrationHash": "sha256:3c5205d2…"
 *   }
 *
 * Starting at 0.17 the same manifest is:
 *
 *   {
 *     "from": "8ee1e7ce…",
 *     "to": "059f3f35…",
 *     "providedInvariants": [],
 *     "createdAt": "2026-…",
 *     "migrationHash": "2be2085f…"   // recomputed over the bare-hex bytes
 *   }
 *
 * Format-preserving edit: hash literals are rewritten in place via a targeted
 * pattern (`"sha256:<64 hex>"` / `"sha256:empty"`, single- or double-quoted),
 * and the `migrationHash` value is swapped in place. Every other byte (key
 * order, indentation, inline-vs-expanded arrays) is left exactly as the
 * authoring tool wrote it, so diffs stay minimal.
 *
 * Confinement: an on-disk migration package is a `migration.json` paired
 * with a sibling `ops.json`. The walk keys off that pair; within a package
 * directory every `.json` / `.ts` sibling (pre-store contract snapshots,
 * `.d.ts` branded types, the executable `migration.ts`) has its hash
 * literals stripped. Content-addressed store entries
 * (`migrations/snapshots/<hex>/contract.json` + `contract.d.ts`) are also
 * covered, so the codemod handles both the pre-store sibling layout and the
 * store layout — run it BEFORE `scripts/migrate-migrations-layout.mjs` when
 * converting the layout in the same upgrade (the 0.17 migrator accepts only
 * bare-hex trees). Store directory names are the hash's hex, which is
 * unchanged by the prefix drop, so no directory is renamed. Ref files are
 * `refs/*.json` under a directory named `migrations`; each gets old-hash →
 * recomputed-hash repointing plus prefix stripping (which also maps the
 * `sha256:empty` sentinel to `empty`).
 *
 * The hash algorithm is replicated inline (canonicalisation rules from
 * `@internal/framework-components` `canonicalizeJson` + the
 * migration-tools `computeMigrationHash`, which returns bare hex from 0.17)
 * so this script stays self-contained — consumers run it via `pnpm exec tsx`
 * from their project root with no dependency on any `@internal/*` package
 * being resolvable from that root.
 *
 * The codemod is idempotent: an already-bare tree carries no `sha256:`
 * literals and its recomputed hashes match the stored ones, so the edit is a
 * no-op and every file is left untouched.
 *
 * Flags:
 *   --check   dry-run; lists files that still need fixing and exits 1 if
 *             any remain.
 */
import { createHash } from 'node:crypto';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { basename, dirname, join, sep } from 'node:path';

const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build']);

const dryRun = process.argv.includes('--check');
const projectRoot = process.cwd();

// --- Inline canonicalisation + hash --------------------------------------
// Replicated from `@internal/framework-components` `canonicalizeJson`
// (sortKeys + JSON.stringify) and the migration-tools `computeMigrationHash`.
// Kept inline so the script has no `@internal/*` import — pnpm's strict
// node_modules layout won't resolve transitive framework deps from a
// consumer's project root.

function sortKeys(value: unknown): unknown {
  if (value === null || typeof value !== 'object') {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(sortKeys);
  }
  const sorted: Record<string, unknown> = Object.create(null);
  for (const [key, entry] of Object.entries(value).sort(([a], [b]) =>
    a < b ? -1 : a > b ? 1 : 0,
  )) {
    sorted[key] = sortKeys(entry);
  }
  return sorted;
}

function canonicalizeJson(value: unknown): string {
  return JSON.stringify(sortKeys(value));
}

function sha256Hex(input: string): string {
  return createHash('sha256').update(input).digest('hex');
}

/**
 * Content-addressed migration hash over (metadata envelope, ops), 0.17 form:
 * bare hex, no prefix. The `migrationHash` field is stripped before hashing
 * so the same function works at write time (no hash yet) and at recompute
 * time (rehashing an already-attested record over the bare-hex envelope).
 */
function computeMigrationHash(metadata: Record<string, unknown>, ops: unknown): string {
  const { migrationHash: _migrationHash, ...strippedMeta } = metadata;

  const partHashes = [canonicalizeJson(strippedMeta), canonicalizeJson(ops)].map(sha256Hex);
  return sha256Hex(canonicalizeJson(partHashes));
}

// --- Prefix stripping ------------------------------------------------------

// A legacy hash literal: `sha256:` + 64 lowercase hex chars, or the
// empty-tree sentinel `sha256:empty`, in single or double quotes. Quoting is
// required so prose that merely mentions the prefix is never rewritten.
const LEGACY_HASH_LITERAL = /(["'])sha256:([0-9a-f]{64}|empty)\1/g;

function stripHashPrefixes(text: string): string {
  return text.replace(LEGACY_HASH_LITERAL, (_full, quote: string, hash: string) => {
    return `${quote}${hash}${quote}`;
  });
}

function replaceMigrationHash(text: string, oldHash: string, newHash: string): string {
  if (oldHash === newHash) return text;
  const re = new RegExp(`("migrationHash"[ \\t]*:[ \\t]*)"${oldHash}"`);
  if (re.exec(text) === null) {
    throw new Error('could not locate the migrationHash value to replace');
  }
  return text.replace(re, (_full, prefix: string) => `${prefix}"${newHash}"`);
}

// --- Filesystem walk ------------------------------------------------------

interface WalkResult {
  readonly manifests: string[];
  readonly refFiles: string[];
  readonly snapshotFiles: string[];
}

async function findMigrationArtifacts(root: string): Promise<WalkResult> {
  const manifests: string[] = [];
  const refFiles: string[] = [];
  const snapshotFiles: string[] = [];

  async function walk(dir: string): Promise<void> {
    let entries: Awaited<ReturnType<typeof readdir>>;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      // Unreadable directory — skip silently. The consumer's project root may
      // legitimately contain restricted directories.
      return;
    }
    for (const entry of entries) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name)) continue;
        await walk(path);
      } else if (entry.isFile() && entry.name === 'migration.json') {
        manifests.push(path);
      } else if (
        entry.isFile() &&
        entry.name.endsWith('.json') &&
        basename(dir) === 'refs' &&
        dirname(dir).split(sep).includes('migrations')
      ) {
        refFiles.push(path);
      } else if (
        entry.isFile() &&
        (entry.name.endsWith('.json') || entry.name.endsWith('.ts')) &&
        basename(dirname(dir)) === 'snapshots' &&
        dirname(dirname(dir)).split(sep).includes('migrations')
      ) {
        snapshotFiles.push(path);
      }
    }
  }

  await walk(root);
  return {
    manifests: manifests.sort(),
    refFiles: refFiles.sort(),
    snapshotFiles: snapshotFiles.sort(),
  };
}

// --- Per-file transforms ---------------------------------------------------

/** Narrows an arbitrary JSON-parsed value to a plain object (manifest shape). */
function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

type Status = 'already-clean' | 'needs-fix' | 'fixed' | 'skipped-no-ops';

interface Result {
  readonly path: string;
  readonly status: Status;
}

const results: Result[] = [];
/** Old migration hash (as previously stored, prefixed) → recomputed bare hash. */
const migrationHashMap = new Map<string, string>();

async function emit(path: string, before: string, after: string): Promise<Result> {
  if (after === before) {
    return { path, status: 'already-clean' };
  }
  if (!dryRun) await writeFile(path, after, 'utf-8');
  return { path, status: dryRun ? 'needs-fix' : 'fixed' };
}

async function processSibling(path: string): Promise<Result> {
  const raw = await readFile(path, 'utf-8');
  return emit(path, raw, stripHashPrefixes(raw));
}

async function processPackage(manifestPath: string): Promise<Result[]> {
  const raw = await readFile(manifestPath, 'utf-8');

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(
      `${manifestPath}: not valid JSON (${error instanceof Error ? error.message : String(error)})`,
    );
  }
  if (!isJsonObject(parsed)) {
    return [{ path: manifestPath, status: 'already-clean' }]; // not a manifest object
  }

  const packageDir = dirname(manifestPath);

  // A complete on-disk migration package pairs `migration.json` with a sibling
  // `ops.json` (the operations the hash is computed over); without it we cannot
  // recompute the hash, so this is not a package we should touch.
  const opsPath = join(packageDir, 'ops.json');
  let opsRaw: string;
  try {
    opsRaw = await readFile(opsPath, 'utf-8');
  } catch {
    return [{ path: manifestPath, status: 'skipped-no-ops' }];
  }

  const out: Result[] = [];

  // Ops: strip prefixes (e.g. `meta.storageHash` stamps inside operation
  // payloads), then parse the stripped text — the recomputed hash covers the
  // bare-hex operations exactly as they will sit on disk.
  const strippedOpsRaw = stripHashPrefixes(opsRaw);
  const ops: unknown = JSON.parse(strippedOpsRaw);
  out.push(await emit(opsPath, opsRaw, strippedOpsRaw));

  // Manifest: strip prefixes from `from` / `to` (and the sentinel), then
  // recompute `migrationHash` over the bare-hex envelope + bare-hex ops.
  // Canonicalisation is order/whitespace independent, so parsing the stripped
  // text is the right input regardless of on-disk formatting.
  const strippedManifestRaw = stripHashPrefixes(raw);
  const strippedMeta = JSON.parse(strippedManifestRaw);
  if (!isJsonObject(strippedMeta)) {
    throw new Error(`${manifestPath}: manifest is not a JSON object`);
  }
  const newHash = computeMigrationHash(strippedMeta, ops);

  const oldStoredHash = parsed['migrationHash'];
  if (typeof oldStoredHash !== 'string') {
    throw new Error(`${manifestPath}: manifest is missing a string \`migrationHash\` field`);
  }
  const strippedOldHash = stripHashPrefixes(`"${oldStoredHash}"`).slice(1, -1);
  migrationHashMap.set(oldStoredHash, newHash);
  migrationHashMap.set(strippedOldHash, newHash);

  out.push(
    await emit(
      manifestPath,
      raw,
      replaceMigrationHash(strippedManifestRaw, strippedOldHash, newHash),
    ),
  );

  // Siblings: contract snapshots (`*-contract.json`), branded-literal type
  // files (`*.d.ts`), and the executable `migration.ts` all carry contract
  // hash literals whose value is stable — only the prefix drops.
  let entries: Awaited<ReturnType<typeof readdir>>;
  try {
    entries = await readdir(packageDir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (entry.name === 'migration.json' || entry.name === 'ops.json') continue;
    if (!entry.name.endsWith('.json') && !entry.name.endsWith('.ts')) continue;
    out.push(await processSibling(join(packageDir, entry.name)));
  }
  return out;
}

async function processRefFile(path: string): Promise<Result> {
  const raw = await readFile(path, 'utf-8');

  // Repoint at recomputed migration hashes first (a ref stores the migration
  // hash of the package it names), then strip any remaining prefixes — which
  // covers contract-hash refs and maps `sha256:empty` → `empty`.
  let text = raw;
  for (const [oldHash, newHash] of migrationHashMap) {
    if (oldHash === newHash) continue;
    text = text.replaceAll(`"${oldHash}"`, `"${newHash}"`);
  }
  text = stripHashPrefixes(text);

  return emit(path, raw, text);
}

// --- Driver ---------------------------------------------------------------

const { manifests, refFiles, snapshotFiles } = await findMigrationArtifacts(projectRoot);
if (manifests.length === 0 && refFiles.length === 0 && snapshotFiles.length === 0) {
  console.error(`No migration artifacts found under ${projectRoot}.`);
  process.exit(1);
}

for (const manifestPath of manifests) {
  results.push(...(await processPackage(manifestPath)));
}
for (const snapshotPath of snapshotFiles) {
  results.push(await processSibling(snapshotPath));
}
for (const refPath of refFiles) {
  results.push(await processRefFile(refPath));
}

let changed = 0;
let alreadyClean = 0;
let skipped = 0;
for (const result of results) {
  const rel = result.path.slice(projectRoot.length + 1);
  if (result.status === 'already-clean') {
    alreadyClean += 1;
  } else if (result.status === 'skipped-no-ops') {
    skipped += 1;
    console.log(`SKIP  ${rel}  (no sibling ops.json — not a migration package)`);
  } else {
    changed += 1;
    const verb = dryRun ? 'WOULD FIX' : 'FIXED';
    console.log(`${verb} ${rel}`);
  }
}

console.log();
console.log(
  `${results.length} file(s) scanned: ${changed} ${dryRun ? 'needing fix' : 'fixed'}, ${alreadyClean} already clean${skipped > 0 ? `, ${skipped} skipped (no ops.json)` : ''}.`,
);

if (dryRun && changed > 0) process.exit(1);

/**
 * Removes the inlined `fromContract` / `toContract` fields from every
 * committed `migration.json` manifest reachable from the project root.
 *
 * Background: starting at the 0.9 release, `migration.json` no longer
 * carries `fromContract` / `toContract` (the schema rejects them as
 * unknown keys). The destination contract continues to live next door
 * as `end-contract.json` (and the source as `start-contract.json`); the
 * manifest copy was redundant. `migrationHash` is unaffected — it was
 * already computed without those two fields, so stripping them does
 * not change the stored hash.
 *
 * Behaviour:
 * - Walks the project root recursively, ignoring `node_modules`, `.git`,
 *   `dist`, and `build`. Picks up every file named `migration.json`
 *   whose JSON object has the migration-manifest shape (`from`, `to`,
 *   and `migrationHash` keys). Other `migration.json` files (e.g.
 *   unrelated artefacts that happen to share the name) are skipped.
 * - Manifests that already lack both removed keys are left untouched.
 * - Manifests with either removed key are rewritten with the two key /
 *   value spans excised at the text level, so the formatting of all
 *   surviving fields (whitespace, inline-vs-multiline arrays, key
 *   ordering, trailing newline) is preserved byte-for-byte. Only the
 *   key being removed and its trailing comma+newline disappear from
 *   the diff.
 * - Idempotent: re-running the script after success is a no-op.
 *
 * Flags:
 *   --check   dry-run; exit 1 if any manifest still needs fixing.
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const REMOVED_KEYS = ['fromContract', 'toContract'] as const;
const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build']);

const dryRun = process.argv.includes('--check');
const projectRoot = process.cwd();

interface Result {
  readonly path: string;
  readonly status: 'already-clean' | 'needs-fix' | 'fixed';
  readonly removed: readonly string[];
}

async function findManifests(root: string): Promise<string[]> {
  const out: string[] = [];

  async function walk(dir: string): Promise<void> {
    const entries = await readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name)) continue;
        await walk(join(dir, entry.name));
      } else if (entry.isFile() && entry.name === 'migration.json') {
        const path = join(dir, entry.name);
        try {
          const parsed: unknown = JSON.parse(await readFile(path, 'utf-8'));
          if (looksLikeMigrationManifest(parsed)) out.push(path);
        } catch {
          // Not valid JSON, or not the manifest shape — skip silently.
        }
      }
    }
  }

  await walk(root);
  return out.sort();
}

function looksLikeMigrationManifest(value: unknown): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null) return false;
  const obj = value as Record<string, unknown>;
  return 'from' in obj && 'to' in obj && 'migrationHash' in obj;
}

/**
 * Find the end index (exclusive) of a JSON value starting at `start`
 * inside `text`. Handles strings, numbers, booleans, null, arrays, and
 * objects. Brace / bracket nesting is tracked while respecting string
 * literals (with escapes). Throws if `text` is not well-formed JSON
 * starting at `start`.
 */
function jsonValueEnd(text: string, start: number): number {
  const head = text[start];
  let depth = 0;
  let inString = false;
  let inEscape = false;

  if (head === '"') {
    let i = start + 1;
    while (i < text.length) {
      const ch = text[i];
      if (inEscape) inEscape = false;
      else if (ch === '\\') inEscape = true;
      else if (ch === '"') return i + 1;
      i += 1;
    }
    throw new Error(`Unterminated string starting at ${start}`);
  }

  if (head === '{' || head === '[') {
    let i = start;
    while (i < text.length) {
      const ch = text[i];
      if (inString) {
        if (inEscape) inEscape = false;
        else if (ch === '\\') inEscape = true;
        else if (ch === '"') inString = false;
      } else {
        if (ch === '"') inString = true;
        else if (ch === '{' || ch === '[') depth += 1;
        else if (ch === '}' || ch === ']') {
          depth -= 1;
          if (depth === 0) return i + 1;
        }
      }
      i += 1;
    }
    throw new Error(`Unterminated container starting at ${start}`);
  }

  let i = start;
  while (i < text.length && !',}\n\r\t '.includes(text[i] ?? '')) i += 1;
  return i;
}

/**
 * Remove a top-level key (and its `: value` and trailing comma) from a
 * pretty-printed JSON object text. Returns the new text. If the key
 * isn't present, returns the input unchanged.
 *
 * Preserves all surrounding whitespace and the formatting of every
 * other field byte-for-byte. Handles both "key in the middle" (eats the
 * trailing comma + newline) and "key at the end" (eats the leading
 * comma + newline).
 */
function removeTopLevelKey(text: string, key: string): string {
  const needle = `"${key}"`;
  const keyIndex = text.indexOf(needle);
  if (keyIndex < 0) return text;

  let cursor = keyIndex + needle.length;
  while (cursor < text.length && /\s/.test(text[cursor] ?? '')) cursor += 1;
  if (text[cursor] !== ':') {
    throw new Error(`Expected ':' after ${needle} at ${cursor}`);
  }
  cursor += 1;
  while (cursor < text.length && /\s/.test(text[cursor] ?? '')) cursor += 1;

  const valueEnd = jsonValueEnd(text, cursor);

  let removeStart = keyIndex;
  let removeEnd = valueEnd;

  if (text[removeEnd] === ',') {
    removeEnd += 1;
    if (text[removeEnd] === '\n') removeEnd += 1;
    let lineStart = removeStart;
    while (lineStart > 0 && text[lineStart - 1] !== '\n') lineStart -= 1;
    if (text.slice(lineStart, removeStart).trim() === '') removeStart = lineStart;
  } else {
    let back = removeStart - 1;
    while (back > 0 && /[ \t]/.test(text[back] ?? '')) back -= 1;
    if (text[back] === '\n') {
      let prev = back - 1;
      while (prev > 0 && /[ \t]/.test(text[prev] ?? '')) prev -= 1;
      if (text[prev] === ',') {
        removeStart = prev;
        if (text[removeEnd] === '\n') removeEnd += 1;
      }
    }
  }

  return text.slice(0, removeStart) + text.slice(removeEnd);
}

async function processManifest(path: string): Promise<Result> {
  const raw = await readFile(path, 'utf-8');
  const data: Record<string, unknown> = JSON.parse(raw);
  const removed = REMOVED_KEYS.filter((key) => key in data);
  if (removed.length === 0) return { path, status: 'already-clean', removed: [] };

  let stripped = raw;
  for (const key of removed) stripped = removeTopLevelKey(stripped, key);

  // Sanity: stripped output must still be valid JSON and must agree on
  // every field except the two we removed.
  const reparsed: Record<string, unknown> = JSON.parse(stripped);
  for (const key of removed) {
    if (key in reparsed) {
      throw new Error(`Internal: ${key} survived strip in ${path}`);
    }
  }

  if (!dryRun) await writeFile(path, stripped, 'utf-8');
  return { path, status: dryRun ? 'needs-fix' : 'fixed', removed };
}

const manifests = await findManifests(projectRoot);
if (manifests.length === 0) {
  console.error(`No migration.json files found under ${projectRoot}.`);
  process.exit(1);
}

let changed = 0;
let alreadyClean = 0;
for (const path of manifests) {
  const result = await processManifest(path);
  const rel = path.slice(projectRoot.length + 1);
  if (result.status === 'already-clean') {
    alreadyClean += 1;
    console.log(`OK    ${rel}  (already clean)`);
  } else {
    changed += 1;
    const verb = dryRun ? 'WOULD FIX' : 'FIXED';
    console.log(`${verb} ${rel}  (removed: ${result.removed.join(', ')})`);
  }
}

console.log();
console.log(
  `${manifests.length} manifest(s) scanned: ${changed} ${dryRun ? 'needing fix' : 'fixed'}, ${alreadyClean} already clean.`,
);

if (dryRun && changed > 0) process.exit(1);

