  for (const candidate of contractDtsCandidates(configDir)) {
    if (!(await pathExists(candidate))) continue;
    const raw = await readFile(candidate, 'utf-8');
    if (contractDtsNeedsDomainPlaneMigration(raw)) return true;
  }
  return false;
}

