    const existingProposal = await db.orm.public.Proposal
      .where({
        projectId,
        freelancerId: user.userId,
      })
      .first();

    if (existingProposal) {
      throw new ApiError(
        "PROPOSAL_ALREADY_EXISTS",
        "You have already submitted a proposal for this project",
        409,
      );
    }

