"use client";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { signup } from "@/src/lib/api";

export default function RegisterPage() {
  const [name, setName] = useState("");
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("freelancer");
  const [msg, setMsg] = useState("");

  async function handle(e: React.FormEvent) {
    e.preventDefault();
    try {
      await signup({ name, email, password, role: role as any });
      setMsg("Registered! Redirecting to login...");
      router.replace("/login");
    } catch (err: any) {
      setMsg(err?.message || "Failed");
    }
  }

  return (
    <main className="shell"><h1>Register</h1>
    <form onSubmit={handle} style={{ display: "grid", gap: "0.75rem" }}>
      <input placeholder="Name" value={name} onChange={e => setName(e.target.value)} required />
      <input placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} required />
      <input type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} required />
      <select value={role} onChange={e => setRole(e.target.value)}><option value="client">Client</option><option value="freelancer">Freelancer</option></select>
      <button>Register</button>
    </form>
    <p>{msg}</p>
    </main>
  );
}

const API_BASE_URL = "/api";

export interface User {
    id: string;  
    name: string;
    email: string;
    role: "client" | "freelancer";
}      

export interface Project {
    id: string;  
    title: string;
    description: string;
    category: string;
    budgetMin: number;
    budgetMax: number;
    deadline: string;
    status: "open" | "in_progress";
    clientName: string;
    proposalCount: number;
    createdAt?: string;
}  

export interface Proposal {
  id: string;
  projectId: string;
  projectTitle?: string;
  freelancerId?: string;
  freelancerName?: string;
  coverLetter: string;
  proposedPrice: number;
  estimatedDuration: number;
  status: "pending" | "accepted" | "rejected";
  createdAt: string;
}

export interface Contract {
  id: string;
  projectId: string;
  projectTitle: string;
  clientId: string;
  clientName: string;
  freelancerId: string;
  freelancerName: string;
  amount: number;
  status: "active";
  createdAt: string;
}

async function request<T>(
  path: string,      
  options?: RequestInit,
): Promise<T> {
  const response = await fetch(`${API_BASE_URL}${path}`, {
    ...options,      
    headers: {
      "Content-Type": "application/json",      
      ...options?.headers,
    },      
    credentials: "include",
  });      

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    const error = new Error(data.message ?? "Something went wrong");
    (error as any).code = data.error;
    throw error;
  }      

  return data;
}      

export async function signup(data: {
  name: string;    
  email: string;
  password: string;
  role: "client" | "freelancer";
}) {
  return request<{
    message: string;    
    user: User;
  }>("/auth/signup", {
    method: "POST",    
    body: JSON.stringify(data),
  });    
}    

export async function login(data: {
  email: string;    
  password: string;
}) {
  return request<{
    message: string;    
    user: User;
  }>("/auth/login", {
    method: "POST",    
    body: JSON.stringify(data),
  });    
}    

export async function getCurrentUser() {
  return request<{
    user: {
      userId: string;    
      role: "client" | "freelancer";
      email: string;
    };    
  }>("/auth/me");    
}    

export async function getProjects(filters?: {
  category?: string;  
  minBudget?: number;
  maxBudget?: number;
}) {
  const params = new URLSearchParams();  

  if (filters?.category) {
    params.set("category", filters.category);  
  }  

  if (filters?.minBudget !== undefined) {
    params.set("minBudget", String(filters.minBudget));  
  }  

  if (filters?.maxBudget !== undefined) {
    params.set("maxBudget", String(filters.maxBudget));  
  }  

  const query = params.toString();

  return request<{
    projects: Project[];  
  }>(`/projects${query ? `?${query}` : ""}`);  
}  

export async function getProject(projectId: string) {
  return request<{
    project: Project;  
  }>(`/projects/${projectId}`);  
}  

export async function submitProposal(
  projectId: string,
  data: {
    coverLetter: string;
    proposedPrice: number;
    estimatedDuration: number;
  },
) {
  return request<{
    message: string;
    proposal: Proposal;
  }>(`/projects/${projectId}/proposals`, {
    method: "POST",
    body: JSON.stringify(data),
  });
}

export async function getProjectProposals(projectId: string) {
  return request<{
    proposals: Proposal[];
  }>(`/projects/${projectId}/proposals`);
}

export async function getMyProposals() {
  return request<{
    proposals: Proposal[];
  }>("/proposals/mine");
}

export async function acceptProposal(proposalId: string) {
  return request<{
    message: string;
    proposal: Proposal;
    contract: Contract;
  }>(`/proposals/${proposalId}/accept`, {
    method: "PUT",
  });
}

export async function getContracts() {
  return request<{
    contracts: Contract[];
  }>("/contracts");
}

import bcrypt from "bcryptjs";
import { SignJWT, jwtVerify, type JWTPayload } from "jose";
import { NextResponse } from "next/server";

const AUTH_COOKIE = "auth_token";

const JWT_SECRET = process.env.JWT_SECRET;

if (!JWT_SECRET) {
  throw new Error("JWT_SECRET is not defined");
}

const secret = new TextEncoder().encode(JWT_SECRET);

export interface AuthPayload extends JWTPayload {
  userId: string;
  role: "client" | "freelancer";
  email: string;
}

export async function hashPassword(password: string) {
  return bcrypt.hash(password, 12);
}

export async function verifyPassword(
  password: string,
  hashedPassword: string,
) {
  return bcrypt.compare(password, hashedPassword);
}

export async function signToken(payload: AuthPayload) {
  return new SignJWT(payload)
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("7d")
    .sign(secret);
}

export async function verifyToken(token: string): Promise<AuthPayload> {
  const { payload } = await jwtVerify(token, secret);

  return {
    userId: payload.userId as string,
    role: payload.role as "client" | "freelancer",
    email: payload.email as string,
  };
}

export function clearAuthCookie(response: NextResponse) {
  response.cookies.set({
    name: AUTH_COOKIE,
    value: "",
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 0,
  });
}

export type ApiErrorCode =
    | "INTERNAL_SERVER_ERROR"
    | "INVALID_REQUEST"
    | "UNAUTHORIZED"
    | "FORBIDDEN"
    | "INVALID_CREDENTIALS"
    | "EMAIL_ALREADY_EXISTS"
    | "PROJECT_NOT_FOUND"
    | "PROJECT_NOT_OPEN"
    | "PROPOSAL_ALREADY_EXISTS"
    | "PROPOSAL_NOT_FOUND"
    | "PROPOSAL_ALREADY_PROCESSED";

export class ApiError extends Error {
    constructor(
        public readonly code: ApiErrorCode,
        message: string,
        public readonly status: number,
    ) {
        super(message);

        this.name = "ApiError";
    }
}

import { cookies } from "next/headers";

import { verifyToken, type AuthPayload } from "@/src/lib/auth";
import { ApiError } from "@/src/lib/errors";

const AUTH_COOKIE = "auth_token";

export async function getCurrentUser(): Promise<AuthPayload> {
  const cookieStore = await cookies();

  const token = cookieStore.get(AUTH_COOKIE)?.value;

  if (!token) {
    throw new ApiError(
      "UNAUTHORIZED",
      "Authentication required",
      401,
    );
  }

  try {
    return await verifyToken(token);
  } catch {
    throw new ApiError(
      "UNAUTHORIZED",
      "Invalid or expired authentication token",
      401,
    );
  }
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

const protectedPaths = ["/dashboard", "/create-project", "/contracts", "/proposals/mine"];

export function middleware(req: NextRequest) {
  const { pathname } = req.nextUrl;
  const isProtected = protectedPaths.some(p => pathname === p || pathname.startsWith(p + "/"));
  if (isProtected) {
    const cookie = req.cookies.get("auth_token");
    if (!cookie) return NextResponse.redirect(new URL("/login", req.url));
  }
  return NextResponse.next();
}

