import "temporal-polyfill/full/global";

import postgres from "@prisma/orm-postgres/runtime";

import service from "../../service.ts";
import type { Contract } from "./contract.d.ts";
import contractJson from "./contract.json" with { type: "json" };

function loadComposerDatabase() {
  try {
    return service.load().database.client;
  } catch {
    return undefined;
  }
}

export const db =
  loadComposerDatabase() ??
  (process.env.DATABASE_URL
    ? postgres<Contract>({ contractJson, url: process.env.DATABASE_URL })
    : postgres<Contract>({ contractJson }));

let connection: Promise<void> | undefined;

export function connectDatabase(): Promise<void> {
  connection ??= db.connect().then(() => undefined).catch((error: unknown) => {
    connection = undefined;
    throw error;
  });
  return connection;
}

import { connectDatabase, db } from "./db.ts";
import { hashPassword } from "../lib/auth";

const users = [
  { name: "Alice", email: "alice@prisma.io", password: "password123", role: "client" as const },
  { name: "Bob", email: "bob@prisma.io", password: "password123", role: "freelancer" as const },
];

let pending: Promise<void> | undefined;
export function seed() {
  pending ??= (async () => {
    await connectDatabase();
    for (const u of users) {
      await db.orm.public.User.upsert({ create: { ...u, password: await hashPassword(u.password) }, update: {}, conflictOn: { email: u.email } });
    }
  })();
  return pending;
}

import { z } from "zod";

export const signupSchema = z.object({
  name: z.string().min(1, "Name is required"),
  email: z.email("Invalid email address"),
  password: z.string().min(8, "Password must be at least 8 characters"),
  role: z.enum(["client", "freelancer"]),
});

export const loginSchema = z.object({
  email: z.email("Invalid email address"),
  password: z.string().min(1, "Password is required"),
});

export type SignupInput = z.infer<typeof signupSchema>;
export type LoginInput = z.infer<typeof loginSchema>;

import { Temporal } from "temporal-polyfill";
import { z } from "zod";

export const createProjectSchema = z
  .object({
    title: z.string().min(1, "Title is required"),
    description: z.string().min(1, "Description is required"),
    category: z.string().min(1, "Category is required"),
    budgetMin: z.number().int().positive("Minimum budget must be greater than 0"),
    budgetMax: z.number().int().positive("Maximum budget must be greater than 0"),
    deadline: z.iso.datetime(),
  })
  .refine((data) => data.budgetMax >= data.budgetMin, {
    message:
      "Maximum budget must be greater than or equal to minimum budget",
    path: ["budgetMax"],
  })
  .refine(
    (data) => {
      const deadline = Temporal.Instant.from(data.deadline);
      const now = Temporal.Now.instant();

      return deadline.epochMilliseconds > now.epochMilliseconds;
    },
    {
      message: "Deadline must be in the future",
      path: ["deadline"],
    },
  );

export const projectFilterSchema = z.object({
  category: z.string().optional(),
  minBudget: z.coerce.number().int().positive().optional(),
  maxBudget: z.coerce.number().int().positive().optional(),
});

export type CreateProjectInput = z.infer<typeof createProjectSchema>;

